Un GPS calcula el tiempo mínimo entre ciudades; `tramos[c]` lista `[ciudad, minutos]`:

function minutosHasta(tramos, origen, destino) {
  const mejor = tramos.map(() => Infinity);
  const cerrada = tramos.map(() => false);
  mejor[origen] = 0;
  for (let paso = 0; paso < tramos.length; paso++) {
    let u = -1;
    for (let i = 0; i < tramos.length; i++) {
      if (!cerrada[i] && mejor[i] < Infinity && (u === -1 || mejor[i] < mejor[u])) u = i;
    }
    if (u === -1) break;
    cerrada[u] = true;
    for (const [v, m] of tramos[u]) {
      if (mejor[u] + m < mejor[v]) mejor[v] = mejor[u] + m;
    }
  }
  return mejor[destino] === Infinity ? -1 : mejor[destino];
}
